do $reylo$ declare s regclass := 'public.inv_no'; goal numeric := 100; reach numeric; c record; begin for c in select d.refobjid::regclass as rel, a.attname, a.atttypid in ('int2'::regtype, 'int4'::regtype, 'int8'::regtype) as plain from pg_depend d join pg_attribute a on a.attrelid = d.refobjid and a.attnum = d.refobjsubid where d.classid = 'pg_class'::regclass and d.objid = s and d.refclassid = 'pg_class'::regclass and d.deptype in ('a', 'i') union all select ad.adrelid::regclass, a.attname, a.atttypid in ('int2'::regtype, 'int4'::regtype, 'int8'::regtype) and r.relkind in ('r', 'p') and pg_get_expr(ad.adbin, ad.adrelid) = format('nextval(%L::regclass)', s::text) from pg_depend d join pg_attrdef ad on ad.oid = d.objid join pg_attribute a on a.attrelid = ad.adrelid and a.attnum = ad.adnum join pg_class r on r.oid = ad.adrelid where d.classid = 'pg_attrdef'::regclass and d.refclassid = 'pg_class'::regclass and d.refobjid = s union all select null, null, false from pg_depend d where d.classid = 'pg_type'::regclass and d.refclassid = 'pg_class'::regclass and d.refobjid = s loop if not c.plain then return; end if; begin execute format('lock table %s in share mode', c.rel); exception when insufficient_privilege then return; end; execute format('select max(%I)::numeric + 1 from %s', c.attname, c.rel) into reach; if reach > goal and reach between 1 and 9223372036854775807 then goal := reach; end if; end loop; perform set_config('reylo.sequence_goal', goal::text, true); end $reylo$;
alter sequence inv_no as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 100 cache 1 no cycle;
do $reylo$ declare s regclass := 'public.inv_no'; goal numeric := nullif(current_setting('reylo.sequence_goal', true), '')::numeric; stands numeric; begin perform set_config('reylo.sequence_goal', '', true); if goal is null then return; end if; execute format('select case when is_called then last_value::numeric + (1) else last_value end from %s', s) into stands; if goal > stands then execute format('alter sequence %s restart with %s', s, goal); end if; end $reylo$;
